Vietnamese:
```java
import java.util.Map;

public class ClassX {
    /**
     * Xác thực tiêu đề token để đảm bảo thuật toán được hỗ trợ.
     * 
     * Hàm kiểm tra xem trường 'alg' trong tiêu đề có chứa 'HS256' hay không.
     *
     * @param header Map chứa các trường tiêu đề của token.
     * @throws IllegalArgumentException nếu thuật toán không phải là 'HS256' hoặc trường 'alg' bị thiếu.
     */
    public void validateTokenHeader(Map<String, String> header) {
        if (header == null || !header.containsKey("alg")) {
            throw new IllegalArgumentException("Token header must contain 'alg' field.");
        }

        String algorithm = header.get("alg");
        if (!"HS256".equals(algorithm)) {
            throw new IllegalArgumentException("Unsupported algorithm: " + algorithm + ". Only HS256 is supported.");
        }
    }
}
