import java.io.File;

public class ClassX {
    /**
     * Extrahiert ein bestimmtes Mitglied aus einem Archiv (simuliert).
     * 
     * Die Funktion überprüft, ob der Mitgliedsname mit einem Schrägstrich beginnt, um absolute Pfade zu verhindern.
     *
     * @param archive Das Archiv, aus dem das Mitglied extrahiert werden soll.
     * @param memberName Der Name des zu extrahierenden Mitglieds.
     * @return true, wenn die Extraktion erfolgreich simuliert wurde und der Mitgliedsname gültig ist;
     *         false, wenn der Mitgliedsname ungültig ist (beginnt mit einem Schrägstrich) oder ein Fehler auftritt.
     */
    public boolean extractMember(File archive, String memberName) {
        // Überprüfen, ob der Mitgliedsname mit einem Schrägstrich beginnt
        if (memberName == null || memberName.startsWith("/")) {
            System.err.println("Fehler: Der Mitgliedsname darf nicht null sein oder mit einem Schrägstrich beginnen, um absolute Pfade zu verhindern.");
            return false;
