import java.net.URL;

public class ClassX {
    /**
     * Lấy nội dung từ một URL đã được tạo ra sau khi xác thực máy chủ.
     * 
     * Hàm này làm sạch máy chủ bằng cách kiểm tra các ký tự không hợp lệ như khoảng trắng.
     *
     * @param url URL đã được xác thực.
     * @return Tên máy chủ đã được làm sạch, hoặc chuỗi rỗng nếu URL không có máy chủ.
     */
    public String getCleanedHostFromUrl(URL url) {
        if (url == null) {
            return "";
        }

        String host = url.getHost();
        if (host == null) {
            return "";
        }

        // Loại bỏ các ký tự không hợp lệ.
        // Giữ lại chữ cái, số, dấu gạch ngang và dấu chấm (các ký tự hợp lệ trong hostname).
        // Thay thế bất kỳ ký tự nào khác bằng chuỗi rỗng.
        return host.replaceAll("[^a-zA-Z0-9.-]", "");
    }
}
