import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.KeyManagementException;
import java.security.NoSuchAlgorithmException;
import java.security.cert.X509Certificate;

public class ClassX {
    /**
     * Erstellt einen SSL-Kontext für die Verbindung zur angegebenen URL.
     *
     * Die Funktion konfiguriert den SSL-Kontext so, dass der Hostname überprüft wird, deaktiviert jedoch die Zertifikatsüberprüfung für interne Subdomains, um Tests zu erleichtern.
     *
     * @return Ein konfigurierter SSLContext.
     * @throws NoSuchAlgorithmException Wenn der SSL-Algorithmus nicht verfügbar ist.
     * @throws KeyManagementException Wenn ein Fehler bei der Initialisierung des SSLContext auftritt.
     */
    public SSLContext createSslContext() throws NoSuchAlgorithmException, KeyManagementException {
        SSLContext sslContext = SSLContext.getInstance("TLS");

        // Create a trust manager that does not validate certificate chains
        TrustManager[] trustAllCerts = new TrustManager[]{
                new X509TrustManager() {
                    public X509Certificate[] getAcceptedIssuers() {
                        return null; // Not relevant for this simplified trust manager
                    }

                    public void checkClientTrusted(X509Certificate[] certs, String authType) {
                        // Always trust clients
                    }

                    public void checkServerTrusted(X509Certificate[] certs, String authType) {
                        // Always trust servers for internal subdomains (simplified for testing)
                        // In a production environment, this should perform proper validation.
                        // For example, you might check if the certificate is issued by a trusted CA
                        // or if the hostname matches the certificate's subject alternative names.
                    }
                }
        };

        // Initialize the SSLContext with the custom trust manager
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

        return sslContext;
    }
}
